import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateSubjectHandler } from "../handlers/updateSubjectHandler";
import type { ApiError } from "../runtime/client";
import type { FactFoldSubjectEntityType } from "../types/FactFoldSubjectEntityType";
import type { UpdateSubjectRequest } from "../types/UpdateSubjectRequest";

type Data = Awaited<ReturnType<typeof updateSubjectHandler>>;
type Vars = { subjectId: FactFoldSubjectEntityType; req: UpdateSubjectRequest };

export function useUpdateSubject(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateSubjectHandler(vars.subjectId, vars.req),
    ...options,
  });
}
